var Io={id:"com.flickertalk.game.beatwagons",name:"Beat Wagons",version:"1.0.5",minCoreVersion:"1.6.0",kind:"game",icon:"musical-notes-outline",components:["ft-beatwagons"],permissions:{live:!0,send:"propose"},summary:"A musical pattern puzzle for the whole family: put the missing wagon in the train and it plays its tune, alone, against FlickerTalk or with the other person in the chat, making trains for each other.",locales:{es:{name:"Vagones con ritmo",summary:"Un puzle musical de patrones para toda la familia: pon el vagón que falta y el tren toca su melodía, solo, contra FlickerTalk o con la otra persona del chat, componiendo trenes el uno para el otro."},pt:{name:"Vagões com ritmo",summary:"Um quebra-cabeça musical de padrões para toda a família: coloque o vagão que falta e o trem toca a sua melodia, sozinho, contra o FlickerTalk ou com a outra pessoa da conversa, compondo trens."},fr:{name:"Wagons en rythme",summary:"Un puzzle musical de motifs pour toute la famille : place le wagon manquant et le train joue sa mélodie, seul, contre FlickerTalk ou avec l’autre personne du chat, qui complète tes trains."},de:{name:"Rhythmuswagen",summary:"Ein musikalisches Musterrätsel für die ganze Familie: Setz den fehlenden Wagen ein, und der Zug spielt seine Melodie, allein, gegen FlickerTalk oder mit der anderen Person im Chat."},it:{name:"Vagoni a ritmo",summary:"Un rompicapo musicale di schemi per tutta la famiglia: metti il vagone mancante e il treno suona la sua melodia, da solo, contro FlickerTalk o con l’altra persona della chat, componendo treni."},ro:{name:"Vagoane cu ritm",summary:"Un puzzle muzical cu modele pentru toată familia: pune vagonul care lipsește și trenul își cântă melodia, singur, contra FlickerTalk sau cu cealaltă persoană din chat, compunând trenuri."},pl:{name:"Rytmiczne wagoniki",summary:"Muzyczna łamigłówka ze wzorami dla całej rodziny: wstaw brakujący wagon, a pociąg zagra melodię — samodzielnie, przeciw FlickerTalk albo z drugą osobą z czatu, układając pociągi dla siebie."},ru:{name:"Ритмичные вагончики",summary:"Музыкальная головоломка с узорами для всей семьи: поставь недостающий вагон, и поезд сыграет мелодию — в одиночку, против FlickerTalk или с собеседником, составляя поезда друг для друга."},uk:{name:"Ритмічні вагончики",summary:"Музична головоломка з візерунками для всієї родини: постав вагон, якого бракує, і потяг зіграє мелодію — наодинці, проти FlickerTalk або зі співрозмовником, складаючи потяги одне для одного."},tr:{name:"Ritimli Vagonlar",summary:"Tüm aile için müzikli bir örüntü bulmacası: eksik vagonu yerine koy, tren melodisini çalsın; tek başına, FlickerTalk'a karşı ya da sohbetteki kişiyle birbirinize tren kurarak."},ar:{name:"عربات الإيقاع",summary:"لغز أنماط موسيقي لكل العائلة: ضع العربة الناقصة فيعزف القطار لحنه، وحدك أو ضد FlickerTalk أو مع الشخص الآخر في المحادثة، يركّب كلٌّ منكما قطارات للآخر."},hi:{name:"ताल के डिब्बे",summary:"पूरे परिवार के लिए संगीत भरी क्रम पहेली: छूटा हुआ डिब्बा लगाएँ और रेलगाड़ी अपनी धुन बजाएगी, अकेले, FlickerTalk के ख़िलाफ़ या चैट के दूसरे व्यक्ति के साथ, एक-दूसरे के लिए रेलगाड़ियाँ बनाकर।"},bn:{name:"তালের বগি",summary:"পুরো পরিবারের জন্য সুরেলা নকশার ধাঁধা: হারানো বগিটি বসান আর ট্রেন তার সুর বাজাবে, একা, FlickerTalk-এর বিরুদ্ধে বা চ্যাটের অন্য মানুষটির সঙ্গে, একে অপরের জন্য ট্রেন সাজিয়ে।"},id:{name:"Gerbong Irama",summary:"Teka-teki pola bermusik untuk seluruh keluarga: pasang gerbong yang hilang dan kereta memainkan lagunya, sendiri, melawan FlickerTalk, atau dengan orang lain di obrolan, saling menyusun kereta."},vi:{name:"Toa tàu nhịp điệu",summary:"Trò giải đố quy luật có âm nhạc cho cả gia đình: đặt toa còn thiếu và đoàn tàu chơi giai điệu của nó, một mình, đấu với FlickerTalk hoặc cùng người kia trong cuộc trò chuyện, xếp tàu cho nhau."},th:{name:"ตู้รถไฟจังหวะ",summary:"ปริศนาแบบรูปพร้อมเสียงดนตรีสำหรับทั้งครอบครัว: วางตู้ที่หายไปแล้วรถไฟจะเล่นทำนอง เล่นคนเดียว เล่นกับ FlickerTalk หรือกับอีกคนในแชต โดยจัดขบวนรถไฟให้กันและกัน"},ja:{name:"リズム列車",summary:"家族みんなで楽しめる音楽のパターンパズル。足りない車両を入れると列車がメロディーをかなでます。ひとりで、FlickerTalk を相手に、またはチャットの相手とおたがいに列車をつくって遊べます。"},ko:{name:"리듬 기차",summary:"온 가족이 즐기는 음악 규칙 퍼즐: 빠진 객차를 넣으면 기차가 멜로디를 연주합니다. 혼자서, FlickerTalk를 상대로, 또는 채팅 상대와 서로 기차를 꾸며 주며 즐기세요."},"zh-CN":{name:"节奏车厢",summary:"适合全家的音乐规律谜题：放上缺少的车厢，火车就会奏出旋律。可以独自玩、和 FlickerTalk 对玩，或与聊天中的对方互相编火车。"},"zh-TW":{name:"節奏車廂",summary:"適合全家的音樂規律謎題：放上缺少的車廂，火車就會奏出旋律。可以獨自玩、和 FlickerTalk 對玩，或與聊天中的對方互相編火車。"}}};var ce=Math.PI*2,F=(e,n=0,t=1)=>Math.min(t,Math.max(n,Number.isFinite(e)?e:n)),Me=e=>1-(1-F(e))**3;var ue=(e,n,t)=>e+(n-e)*t;function w(e,n,t,o,r,i){let s=Math.max(0,Math.min(Math.abs(o)/2,Math.abs(r)/2,i));e.beginPath(),e.moveTo(n+s,t),e.arcTo(n+o,t,n+o,t+r,s),e.arcTo(n+o,t+r,n,t+r,s),e.arcTo(n,t+r,n,t,s),e.arcTo(n,t,n+o,t,s),e.closePath()}var Nn=new WeakMap,dc=3;function Vi(e,{ink:n,colour:t},o){if(!t)return o();let r=Nn.get(e);Nn.set(e,{ink:n,colour:t});try{return o()}finally{r?Nn.set(e,r):Nn.delete(e)}}function y(e,n,t,o){n&&(e.fillStyle=n,e.fill());let r=Nn.get(e);r&&t===r.ink&&o>0&&(e.strokeStyle=r.colour,e.lineWidth=o+dc,e.stroke()),t&&o>0&&(e.strokeStyle=t,e.lineWidth=o,e.stroke())}function S(e,n,t,o,r,i=null,s=0){e.beginPath(),e.arc(n,t,Math.max(0,o),0,ce),y(e,r,i,s)}function I(e,n,t,o,r,i,s=null,a=0){e.beginPath(),e.ellipse(n,t,Math.max(0,o),Math.max(0,r),0,0,ce),y(e,i,s,a)}function Z(e,n,t,o=null,r=0){e.beginPath(),n.forEach(([i,s],a)=>a?e.lineTo(i,s):e.moveTo(i,s)),e.closePath(),y(e,t,o,r)}function T(e,n,t,o){e.beginPath(),n.forEach(([r,i],s)=>s?e.lineTo(r,i):e.moveTo(r,i)),e.strokeStyle=t,e.lineWidth=o,e.lineCap="round",e.lineJoin="round",e.stroke()}function Se(e,n,t,o,r=o*.46){e.beginPath();for(let i=0;i<10;i+=1){let s=i%2?r:o,a=-Math.PI/2+i*Math.PI/5,l=n+Math.cos(a)*s,c=t+Math.sin(a)*s;i?e.lineTo(l,c):e.moveTo(l,c)}e.closePath()}function kt(e,n,t,o){let r=Math.max(20,Math.min(38,t*.055))/3;e.save(),e.fillStyle=o,[1,.72,.36].forEach((i,s)=>{s&&(e.globalAlpha=i),e.fillRect(0,s*r,n,r),e.fillRect(0,t-(s+1)*r,n,r)}),e.restore()}fu